<x-layouts.store title="Checkout | Cherry Bellemont"><section class="mx-auto grid max-w-6xl gap-12 px-6 py-16 lg:grid-cols-[1fr_24rem]"><div><p class="uppercase tracking-[.25em] text-gold">Guest checkout</p><h1 class="mt-3 text-5xl">Delivery details</h1><form id="checkout-form" class="mt-10 space-y-5" method="POST" action="{{ route('checkout.store') }}">@csrf @foreach(['customer_name'=>'Full name','customer_email'=>'Email','customer_phone'=>'Phone number','address_line_1'=>'Address line 1','address_line_2'=>'Address line 2 (optional)','city'=>'City or area','state'=>'State','postcode'=>'Postcode','country'=>'Country'] as $field=>$label)<div class="address-field"><label>{{ $label }}</label><input class="field mt-2" name="{{ $field }}" value="{{ old($field, $field === 'customer_name' ? auth()->user()?->name : ($field === 'customer_email' ? auth()->user()?->email : ($field === 'country' ? 'Malaysia' : ''))) }}" @if($field !== 'address_line_2') required @endif>@error($field)<p class="mt-1 text-gold">{{ $message }}</p>@enderror</div>@endforeach<div><label>Delivery instructions (optional)</label><textarea class="field mt-2" name="delivery_instructions">{{ old('delivery_instructions') }}</textarea></div><div><label>Delivery method</label><select id="delivery_method_id" class="field mt-2" name="delivery_method_id" required>@foreach($deliveryMethods as $method)<option value="{{ $method->id }}" data-pickup="{{ $method->is_pickup ? '1' : '0' }}" @selected(old('delivery_method_id')==$method->id)>{{ $method->name }}{{ $method->estimated_days ? ' · '.$method->estimated_days.' days' : '' }}{{ $method->is_pickup ? ' · RM0.00' : '' }}</option>@endforeach</select>@error('delivery_method_id')<p class="mt-1 text-gold">{{ $message }}</p>@enderror</div><div id="shipping-message" class="text-sm text-cream/65">Enter delivery details to calculate shipping.</div><div><p class="mb-2">Payment method</p><label><input type="radio" name="payment_method" value="duitnow" checked> DuitNow manual payment</label><span class="ml-4 text-cream/45">Stripe — coming soon</span></div><button id="place-order" class="luxury-link" type="submit">Place order</button></form></div><aside class="border border-cream/15 p-6"><h2 class="text-2xl">Order summary</h2>@foreach($lines as $line)<div class="mt-5 flex gap-3"><div class="h-16 w-12 shrink-0 overflow-hidden bg-wine-deep">@if($line['product']->image_path)<img class="h-full w-full object-cover" src="{{ asset('storage/' . $line['product']->image_path) }}" alt="{{ $line['product']->name }}">@endif</div><div class="flex flex-1 justify-between gap-3"><span>{{ $line['product']->name }} × {{ $line['quantity'] }}</span><span class="text-gold">RM {{ number_format($line['line_total']/100,2) }}</span></div></div>@endforeach<p class="mt-8 flex justify-between border-t border-cream/15 pt-5"><span>Subtotal</span><span>RM {{ number_format($subtotal/100,2) }}</span></p><p class="mt-3 flex justify-between"><span>Shipping</span><span id="shipping-fee">—</span></p><p class="mt-4 flex justify-between text-xl text-gold"><span>Total</span><span id="grand-total">RM {{ number_format($total/100,2) }}</span></p></aside></section><script>const f=document.getElementById('checkout-form'),m=document.getElementById('delivery_method_id'),msg=document.getElementById('shipping-message'),fee=document.getElementById('shipping-fee'),total=document.getElementById('grand-total'),btn=document.getElementById('place-order'),sub={{ $subtotal/100 }};async function quote(){let pickup=m.options[m.selectedIndex]?.dataset.pickup==='1';document.querySelectorAll('.address-field').forEach(e=>e.style.display=pickup?'none':'block');if(!pickup&&(!f.state.value||!f.city.value||!f.postcode.value)){btn.disabled=true;return}msg.textContent='Calculating shipping…';btn.disabled=true;let r=await fetch('{{ route('shipping.quote') }}',{method:'POST',headers:{'Content-Type':'application/json','X-CSRF-TOKEN':'{{ csrf_token() }}','Accept':'application/json'},body:JSON.stringify({state:f.state.value,city:f.city.value,postcode:f.postcode.value,delivery_method_id:m.value})}),d=await r.json();if(!r.ok){msg.textContent=d.message||Object.values(d.errors||{})[0]?.[0]||'Delivery unavailable.';fee.textContent='—';btn.disabled=true;return}msg.textContent=d.display_label+(d.pickup_location?' · '+d.pickup_location:'');fee.textContent='RM '+Number(d.shipping_fee).toFixed(2);total.textContent='RM '+(sub+Number(d.shipping_fee)).toFixed(2);btn.disabled=false}['state','city','postcode'].forEach(n=>f[n].addEventListener('input',quote));m.addEventListener('change',quote);quote();</script></x-layouts.store>
